window.DADOS=window.DADOS||{};window.DADOS["18A1"]={"cod": "18A1", "revisao": [{"id": "r1", "titulo": "MÓDULO 1 — Noções Gerais / Atos de Comércio / Empresário", "prob": "media", "html": "<ul>\n<li><strong>Direito Comercial</strong> = direito privado regulador dos atos necessários às atividades dos comerciantes e dos atos legalmente considerados comerciais</li>\n<li><strong>Principais leis:</strong> CC/2002 (Lei 10.406), LSA (Lei 6.404/76), Lei do Cheque (7.357/85), LPI (9.279/96), LRE (11.101/05), LUG (Dec. 57.663), Lei da Duplicata (5.474/68), Estatuto ME/EPP (LC 123/06)</li>\n<li><strong>CC/2002 unificou</strong> obrigações civis e comerciais — inspirado no modelo italiano de 1942</li>\n<li><strong>Teorias DC:</strong> (1) Direito do Comerciante; (2) Direito dos Atos de Comércio; (3) Direito das Empresas; (4) Direito dos Comerciantes + Atos de Comércio (mais aceita classicamente)</li>\n<li><strong>Características DC:</strong> simplicidade, internacionalidade, rapidez, boa-fé, onerosidade</li>\n<li><strong>DC ≠ Direito Civil:</strong> imóveis e atividade agrícola = regime civil; títulos cambiários = sempre comerciais</li>\n</ul>"}, {"id": "r2", "titulo": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "prob": "alta", "html": "<ul>\n<li><strong>Empresário</strong> (art. 966 CC): quem exerce <em>profissionalmente</em> atividade econômica <em>organizada</em> para produção/circulação de bens ou serviços</li>\n<li><strong>Requisitos:</strong> profissionalismo (habitualidade, pessoalidade, especialidade), atividade econômica, organização (capital, mão de obra, insumos, tecnologia), produção/circulação</li>\n<li><strong>NÃO é empresário</strong> (art. 966 § único): profissão intelectual (científica, literária, artística) — salvo se for <em>elemento de empresa</em></li>\n<li><strong>Empresário Individual:</strong> responsabilidade <em>direta, pessoal e ilimitada</em> (sem separação patrimonial)</li>\n<li><strong>Sociedade Empresária:</strong> responsabilidade dos sócios <em>subsidiária</em> (art. 1.024 CC)</li>\n<li><strong>MEI:</strong> LC 128/08; faturamento até R$ 81 mil/ano; recolhe INSS 5% + ISS + ICMS; não pode ter sócio</li>\n<li><strong>Simples Nacional:</strong> LC 123/06 — ME (até R$360k) e EPP (até R$4,8M)</li>\n<li><strong>Registro:</strong> JUCEX (Junta Comercial) — funções: publicidade, autenticidade, segurança, eficácia</li>\n<li><strong>Nome empresarial:</strong> firma (usa nome dos sócios) ou denominação (fantasia + objeto)</li>\n</ul>"}, {"id": "r3", "titulo": "MÓDULO 3 — Estabelecimento Empresarial / Clientela", "prob": "media", "html": "<ul>\n<li><strong>Estabelecimento</strong> (art. 1.142 CC) = complexo de bens organizado para exercício da empresa</li>\n<li><strong>Aviamento</strong> = capacidade potencial de gerar lucros (intangível)</li>\n<li><strong>Clientela</strong> = conjunto de clientes que frequentam o estabelecimento</li>\n<li><strong>Trespasse</strong> = alienação do estabelecimento empresarial; prazo de 30 dias para credores impugnarem</li>\n<li><strong>No trespasse:</strong> alienante <em>não pode se restabelecer</em> como concorrente por 5 anos (art. 1.147 CC)</li>\n<li><strong>Ponto empresarial:</strong> direito à renovação da locação (ação renovatória) — requisitos: contrato por escrito; prazo mínimo 5 anos; ramo por mínimo 3 anos</li>\n<li><strong>Ação renovatória:</strong> proposta 1 ano antes e até 6 meses antes do término do contrato</li>\n</ul>"}, {"id": "r4", "titulo": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "prob": "alta", "html": "<ul>\n<li><strong>INPI</strong> = órgão responsável pelo registro</li>\n<li><strong>Marca:</strong> sinal distintivo visualmente perceptível; proteção por 10 anos (renováveis indefinidamente)</li>\n<li><strong>Marcas NÃO registráveis:</strong> brasões/emblemas oficiais; letras/números isolados sem forma distintiva; expressões contrárias à moral; siglas de órgãos públicos; sinais genéricos/descritivos; nomes civis de terceiros sem consentimento; obras artísticas protegidas por direito autoral</li>\n<li><strong>Patente de invenção:</strong> 20 anos do depósito | <strong>Modelo de utilidade:</strong> 15 anos</li>\n<li><strong>Desenho Industrial:</strong> 10 anos (renováveis até 25 anos)</li>\n<li><strong>Indicação Geográfica:</strong> Indicação de Procedência + Denominação de Origem</li>\n<li><strong>Crime de concorrência desleal:</strong> art. 195 LPI</li>\n</ul>"}, {"id": "r5", "titulo": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "prob": "media", "html": "<ul>\n<li><strong>Sociedade empresária</strong> (art. 982): tem por objeto atividade de empresário sujeita a registro</li>\n<li><strong>Sociedade simples</strong> = exercício de atividade intelectual</li>\n<li><strong>Princípios:</strong> contrato social plurilateral, personificação jurídica, affectio societatis</li>\n<li><strong>Desconsideração da personalidade jurídica</strong> (art. 50 CC): abuso/desvio de finalidade ou confusão patrimonial → incidente processual (art. 133 CPC)</li>\n<li><strong>Sociedade não personificada:</strong> em comum (sem registro) e em conta de participação</li>\n<li><strong>Contrato social:</strong> pluralidade de sócios, capital social, affectio societatis, participação em lucros e perdas</li>\n</ul>"}, {"id": "r6", "titulo": "MÓDULO 6 — Sociedades Empresárias — Espécies", "prob": "alta", "html": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Tipo</th>\n<th>Responsabilidade</th>\n<th>Registro</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Sociedade em Comum</td>\n<td>ilimitada e solidária (todos)</td>\n<td>sem registro</td>\n</tr>\n<tr>\n<td>Conta de Participação</td>\n<td>sócio ostensivo ilimitada; oculto limitada à participação</td>\n<td>facultativo</td>\n</tr>\n<tr>\n<td>Sociedade Simples</td>\n<td>limitada ou ilimitada conforme contrato</td>\n<td>RCPJ</td>\n</tr>\n<tr>\n<td>Em Nome Coletivo</td>\n<td>todos respondem ilimitada e solidariamente</td>\n<td>JUCEX</td>\n</tr>\n<tr>\n<td>Em Comandita Simples</td>\n<td>comanditado: ilimitada; comanditário: limitada à quota</td>\n<td>JUCEX</td>\n</tr>\n<tr>\n<td>Ltda</td>\n<td>limitada ao valor das quotas</td>\n<td>JUCEX</td>\n</tr>\n<tr>\n<td>S/A</td>\n<td>limitada ao preço de emissão das ações</td>\n<td>JUCEX</td>\n</tr>\n<tr>\n<td>Comandita por Ações</td>\n<td>diretores: ilimitada; demais: limitada</td>\n<td>JUCEX</td>\n</tr>\n</tbody>\n</table></div>"}, {"id": "r7", "titulo": "MÓDULO 7 — Sociedade Limitada", "prob": "alta", "html": "<ul>\n<li><strong>Lei:</strong> arts. 1.052–1.087 CC + LSA subsidiariamente</li>\n<li><strong>Capital:</strong> dividido em quotas; sócios respondem solidariamente pela integralização</li>\n<li><strong>Cessão de quotas:</strong> requer aprovação de sócios com ≥ 3/4 do capital (salvo contrato diferente)</li>\n<li><strong>Administração:</strong> sócio ou não sócio (pessoa física capaz)</li>\n<li><strong>Deliberações:</strong> maioria = mais da metade do capital social; unanimidade = mudança de objeto, fusão, dissolução</li>\n<li><strong>Reunião ou Assembleia:</strong> obrigatória quando &gt;10 sócios; anual para aprovar contas</li>\n<li><strong>Exclusão de sócio:</strong> por justa causa, votação de sócios com ≥ 1/2 do capital restante</li>\n<li><strong>Dissolução:</strong> judicial ou extrajudicial</li>\n</ul>"}, {"id": "r8", "titulo": "MÓDULO 8 — Sociedade Anônima (Lei 6.404/76)", "prob": "alta", "html": "<ul>\n<li><strong>Conceito:</strong> capital dividido em ações; responsabilidade limitada ao preço de emissão das ações subscritas</li>\n<li><strong>Sempre empresarial</strong> independentemente do objeto (art. 1.089 CC)</li>\n<li><strong>Companhia aberta:</strong> ações negociadas em bolsa/mercado; sujeita à CVM</li>\n<li><strong>Companhia fechada:</strong> ações não negociadas publicamente</li>\n<li><strong>Tipos de ações:</strong> ordinárias (direito a voto), preferenciais (privilégios econômicos, podem não ter voto), de gozo/fruição</li>\n<li><strong>Forma das ações:</strong> sempre nominativas (desde Lei 8.021/90; ações ao portador foram extintas)</li>\n<li><strong>Denominação:</strong> usa \"S.A.\" ou \"Companhia\" (não firma)</li>\n<li><strong>Órgãos:</strong> Assembleia Geral (soberana), Conselho de Administração (facultativo em fechada), Diretoria (obrigatória), Conselho Fiscal (facultativo)</li>\n<li><strong>Responsabilidade do acionista:</strong> limitada ao preço de emissão; não há subsidiária pelas obrigações sociais</li>\n</ul>"}], "top5": ["Conceito de empresário (art. 966 CC)", "Tipos de sociedade e responsabilidade dos sócios", "Sociedade Limitada (quotas, cessão, deliberações)", "Sociedade Anônima (ações, tipos, denominação)", "Propriedade Industrial (prazos de patente/marca)"], "questoes": [{"id": "M1-Q1", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q1", "tema": "história/evolução do DC", "enun": "", "gab": "E", "gabLabel": "", "html": "O DC surgiu na <b>Idade Média</b> com as corporações de comerciantes, não na Antiguidade romana (onde havia jus civile aplicado a todos).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q2", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q2", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Teoria do DC como direito dos atos de comércio (Código Napoleônico 1807) — caracteriza como comercial o ato pela sua natureza, não pela pessoa do praticante.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q3", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q3", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Característica do DC: <b>simplicidade</b> (desformalização), internacionalidade, rapidez e boa-fé são os traços marcantes.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q4", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q4", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Autonomia do DC em relação ao DC Civil: regulam campos distintos — imóveis e agricultura = civil; títulos de crédito = sempre comercial.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q5", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q5", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Legislação básica: CC/2002 (Lei 10.406), LSA (6.404/76), Lei do Cheque (7.357/85), LPI (9.279/96), LRE (11.101/05).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q6", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q6", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Teoria mais aceita: DC como direito dos <b>comerciantes + atos de comércio</b> (inclui atos de não comerciantes).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q7", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q7", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "O Código Civil de 2002 <b>revogou</b> o Código Comercial de 1850 e unificou obrigações civis e comerciais, inspirado no modelo italiano de 1942.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q8", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q8", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Boa-fé no DC: posse de boa-fé de título ao portador presume propriedade — função legitimadora amplíssima (diferente do DC Civil).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q9", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q9", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "DC = ramo do <b>Direito Privado</b> (não público), embora contenha normas de Direito Público em certos institutos (falência, transporte).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q10", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q10", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Características do DC: onerosidade, internacionalidade, rapidez, simplicidade e boa-fé (5 características clássicas).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q11", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q11", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Teoria das empresas: DC como direito das empresas — fundamento na organização de capital e trabalho para produção/circulação.", "repete": true, "repeteRef": "conceito Q6", "coment": []}, {"id": "M1-Q12", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q12", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Codificação napoleônica de 1807 influenciou: Nápoles, Bélgica, São Domingos, e indiretamente o <b>Código Comercial Brasileiro de 1850</b>.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q13", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q13", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Direito Econômico ≠ DC: DE é mais amplo, inclui intervenção estatal imperativa na economia; DC é ramo dentro do DE.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q14", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q14", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Direito dos Negócios (Hamel e Lagarde) = amplia o DC para além da circulação de mercadorias, abrange negócios em geral.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q15", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q15", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Art. 966 CC: empresário = quem exerce <b>profissionalmente</b> atividade econômica organizada para produção/circulação de bens ou serviços.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q16", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q16", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Teoria do DC como direito do comerciante: superada, pois não abrange atos comerciais praticados por não comerciantes.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q17", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q17", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "CC/2002: Livro II — \"Do Direito de Empresa\" — reuniu o DC ao Código Civil, revogando o CC Comercial de 1850 na parte de 1ª parte.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M1-Q18", "bloco": "MÓDULO 1 — Noções Gerais / Atos de Comércio", "num": "Q18", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Unificação do Direito Privado: tentativa de Teixeira de Freitas (1867) → não aceita; Suíça (1936) e Itália (1942) realizaram parcialmente.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q1", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q1", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "ME: receita bruta ≤ R$ 360.000/ano; EPP: R$ 360.001 a R$ 4.800.000/ano (LC 123/06 art. 3º). <b>Pegadinha:</b> muitas questões colocam R$ 400k — ERRADO.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q2", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q2", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Empresário casado pode alienar bens imóveis <b>do patrimônio da empresa</b> sem outorga conjugal (são bens empresariais, não pessoais).", "repete": true, "repeteRef": "Q16 conceito patrimonial", "coment": []}, {"id": "M2-Q3", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q3", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "EIRELI: patrimônio social responde pelas dívidas, MAS a separação patrimonial pode ser desconsiderada (art. 50 CC) — não é absoluta. <b>Pegadinha:</b> a alternativa B diz \"em qualquer situação\" → INCORRETA (que é o que a questão pede).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q4", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q4", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "EIRELI: nome deve conter \"EIRELI\" após a firma/denominação; capital mínimo = 100× maior salário mínimo; pessoa natural só pode ter <b>uma</b> EIRELI.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q5", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q5", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Registro de incapaz como sócio: permitido se não exercer administração + capital totalmente integralizado + assistido/representado conforme o caso.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q6", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q6", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Competência para MS contra ato do Presidente da Junta Comercial = <b>Justiça Federal</b> (função federal delegada). Todas as assertivas da questão estavam erradas.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q7", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q7", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Empresário rural: inscrição na Junta Comercial é <b>facultativa</b> (art. 971 CC) e pode ser feita mesmo <b>após</b> início das atividades.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q8", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q8", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Empresário que se torna incapaz: pode continuar a empresa por representante ou assistido; Junta Comercial registra contratos envolvendo incapazes.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q9", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q9", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Livros empresariais: fazem prova <b>contra</b> o empresário sempre; fazem prova <b>a favor</b> quando sem vícios e confirmados por outros subsídios.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q10", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q10", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Nome empresarial: <b>IV e V corretas</b> — o nome NÃO pode ser alienado; a sociedade em conta de participação NÃO tem firma nem denominação.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q11", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q11", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Nome empresarial: vedada a alienação (art. 1.164 CC); princípios: veracidade e novidade.", "repete": true, "repeteRef": "Q10", "coment": []}, {"id": "M2-Q12", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q12", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "ME ≤ R$360k; EPP até R$4,8M — atenção: a pegadinha dos R$400k e dos R$5M aparece em múltiplas questões.", "repete": true, "repeteRef": "Q1", "coment": []}, {"id": "M2-Q13", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q13", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Escrituração: obrigatória para todos os empresários; livro Diário é obrigatório; conservação por 10 anos mínimo.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q14", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q14", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Simples Nacional: não se aplica a empresas com sócio no exterior, com atividade de banco, CNAE vedados, faturamento acima do limite.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q15", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q15", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Junta Comercial: funções de dar publicidade, autenticidade, segurança e eficácia aos atos jurídicos das empresas (art. 8º Lei 8.934/94).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q16", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q16", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Empresário individual: responsabilidade ilimitada, pessoal e direta; sócio de sociedade: subsidiária.", "repete": true, "repeteRef": "conceito Q2", "coment": []}, {"id": "M2-Q17", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q17", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "MEI: pode ter 1 empregado; fatura até R$81k/ano; recolhe INSS 5% + ISS/ICMS fixo; não pode ser sócio de outra empresa.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M2-Q18", "bloco": "MÓDULO 2 — Empresário / Registro / Escrituração / Nome Empresarial", "num": "Q18", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Redesim: sistema integrado de abertura/fechamento de empresas; reduz burocracia; integra DREI, INSS, RFB e municípios.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q1", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q1", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Estabelecimento (art. 1.142 CC) = complexo de bens organizados para exercício da empresa. Inclui bens materiais e imateriais (ponto, clientela, nome).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q2", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q2", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Aviamento = aptidão/capacidade de gerar lucro. É atributo do estabelecimento, não do empresário.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q3", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q3", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "No trespasse: alienante fica proibido de se restabelecer como concorrente por <b>5 anos</b> (art. 1.147 CC), salvo autorização expressa.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q4", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q4", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Trespasse: credores podem impugnar em <b>30 dias</b> após publicação. Antes da quitação das dívidas, o adquirente responde solidariamente com o alienante.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q5", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q5", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Clientela: conjunto de clientes que frequentam o estabelecimento — elemento imaterial integrante do estabelecimento.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q6", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q6", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Ponto empresarial: direito à locação do espaço; protegido pela Lei de Locações (Lei 8.245/91) — ação renovatória.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q7", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q7", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Ação renovatória: requisitos — contrato escrito; prazo mínimo 5 anos (pode ser soma de contratos); ramo mínimo 3 anos; proposta 1 ano antes e até 6 meses antes do término.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q8", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q8", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Penhor do estabelecimento: é possível; difere da hipoteca (imóveis) e da anticrese.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q9", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q9", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Créditos no trespasse: o adquirente assume os contratos vinculados ao estabelecimento, salvo estipulação contrária (art. 1.148 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q10", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q10", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Cláusula de não restabelecimento: 5 anos para alienação definitiva; vigência do contrato para cessão de uso. Limites: territorial e de atividade.", "repete": true, "repeteRef": "Q3", "coment": []}, {"id": "M3-Q11", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q11", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Bem de família do empresário: a moradia pode ser penhorada para dívidas da atividade empresarial contraídas no curso do negócio.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q12", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q12", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Estabelecimento eletrônico (ponto empresarial digital): também protegido, com regras adaptadas à Lei de Locações.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q13", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q13", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Contestação da ação renovatória: locador pode contestar alegando: retomada sincera para uso próprio; reforma substancial; proposta de terceiro melhor.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q14", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q14", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Nome empresarial no trespasse: adquirente pode usar nome do alienante com indicação de \"sucessor\" (art. 1.164 § único CC), se autorizado.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q15", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q15", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Improcedência da renovação: locador pode retomar para uso próprio ou de cônjuge/descendente desde que comprovada a sinceridade (art. 52 L8.245/91).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q16", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q16", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Ação de despejo: cabe após extinção do contrato de locação não residencial não renovada judicialmente.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q17", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q17", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Estabelecimento = universalidade de fato ou de direito? Doutrina majoritária: <b>universalidade de fato</b> (bens reunidos pela vontade do empresário).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M3-Q18", "bloco": "MÓDULO 3 — Estabelecimento Empresarial", "num": "Q18", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Locação empresarial: prazo mínimo de 5 anos para dar direito à renovatória (pode ser por meio de contratos sucessivos).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q1", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q1", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Patente de invenção: 20 anos da data do depósito. <b>Modelo de utilidade:</b> 15 anos. Nunca confundir os prazos.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q2", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q2", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Marcas não registráveis: brasões/emblemas oficiais; letras isoladas; expressão imoral; sigla de órgão público; sinal genérico/descritivo.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q3", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q3", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Registro de marca no INPI: proteção por 10 anos, renováveis indefinidamente por períodos iguais.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q4", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q4", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Patente: requisitos de patenteabilidade — novidade, atividade inventiva e aplicação industrial. Descoberta ≠ invenção.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q5", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q5", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Indicação Geográfica: IP (Indicação de Procedência) = local com reputação; DO (Denominação de Origem) = local + qualidade/características ligadas ao meio.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q6", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q6", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Desenho industrial: 10 anos do depósito, prorrogável por 3 períodos de 5 anos → máximo 25 anos.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q7", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q7", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Crime contra propriedade industrial: art. 195 LPI — concorrência desleal. Inclui divulgar segredo industrial, imitar produto, usar marca alheia.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q8", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q8", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Marca coletiva: identifica produtos/serviços de membros de uma entidade. Marca de certificação: atesta conformidade com normas/especificações.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q9", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q9", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Colidência de marcas: para impedir registro = imitação/reprodução + mesma classe de produtos/serviços + risco de confusão ao consumidor (STJ: 3 requisitos).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q10", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q10", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Licença compulsória de patente: Estado pode conceder em caso de abuso de poder econômico, emergência nacional ou interesse público (art. 68 LPI).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q11", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q11", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Ação de nulidade de patente: proposta pelo INPI ou terceiro com interesse legítimo na <b>Justiça Federal</b>, durante toda a vigência da patente.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q12", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q12", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Topografia de circuito integrado: proteção específica (art. 25 LPI); prazo 10 anos do registro ou 15 anos da criação. [Tema menos cobrado]", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q13", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q13", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Nome civil e marca: nome de terceiro só pode ser registrado como marca com consentimento do titular ou herdeiros.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q14", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q14", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Extinção da patente: vencimento do prazo, renúncia, caducidade (não exploração), falta de pagamento de anuidade ou nulidade.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q15", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q15", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Uso da marca: obrigatório; caducidade da marca por falta de uso por 5 anos consecutivos após a concessão (art. 143 LPI).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q16", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q16", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Marca de alto renome: proteção em todos os ramos de atividade (não apenas na classe registrada) — reconhecida pelo INPI.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q17", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q17", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Segredo industrial: não tem prazo de proteção; protegido enquanto mantido em sigilo; não há registro público.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M4-Q18", "bloco": "MÓDULO 4 — Propriedade Industrial (Lei 9.279/96)", "num": "Q18", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Proteção provisória: desde o depósito do pedido até a concessão — o titular pode cobrar indenização retroativa por uso indevido.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q1", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q1", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Sociedade em comum (sem registro): <b>todos</b> respondem solidária e ilimitadamente; quem contratou perde o benefício de ordem (art. 990 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q2", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q2", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Cônjuges impedidos de constituir sociedade entre si: casados sob <b>comunhão universal</b> ou <b>separação obrigatória</b> (art. 977 CC).", "repete": true, "repeteRef": "nos flashcards", "coment": []}, {"id": "M5-Q3", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q3", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Personalidade jurídica: início com o <b>registro</b> (art. 985 CC). Sem registro = sociedade em comum (não personificada).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q4", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q4", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Sociedade em comum: bens sociais respondem por atos de qualquer sócio, salvo pacto limitativo conhecido pelo terceiro (art. 989 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q5", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q5", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Liquidante: deveres incluem ultimar negócios, realizar ativo, pagar passivo e partilhar o remanescente (art. 1.103 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q6", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q6", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Desconsideração da personalidade jurídica inversa: responsabiliza a <b>sociedade</b> por dívidas pessoais dos sócios (art. 50 §§ 2º e 3º CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q7", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q7", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Morte do sócio em sociedade simples: <b>resolução</b> em relação ao sócio (não dissolução total); liquidação da quota pelo balanço especial (art. 1.028 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q8", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q8", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Sociedades não personificadas: em comum + em conta de participação. NÃO são: simples, cooperativa, em comandita.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q9", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q9", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Resolução da sociedade em relação ao sócio: morte (art. 1.028) + exclusão judicial por falta grave (art. 1.030) → não são causas de dissolução total.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q10", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q10", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Exclusão extrajudicial de sócio: votos de sócios com + de metade do capital social (excluindo o sócio excluído do cômputo).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q11", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q11", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Affectio societatis: elemento essencial do contrato social = intenção/vontade de cooperar para fins comuns.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q12", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q12", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Registro constitui a personalidade jurídica; sem ele, a sociedade é em comum, todos respondem solidária e ilimitadamente.", "repete": true, "repeteRef": "Q3", "coment": []}, {"id": "M5-Q13", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q13", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Sociedade em conta de participação: sócio ostensivo assume obrigações; sócio participante (oculto) responde apenas entre si. Sem personalidade jurídica.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q14", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q14", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Contrato social plurilateral: todos os sócios participam; cada um tem obrigações com os demais e com a sociedade.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q15", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q15", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Dissolução total vs. resolução parcial: dissolução = extinção da sociedade; resolução = saída de um sócio (sociedade continua).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q16", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q16", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Administração societária: o administrador obriga a sociedade nos limites dos poderes outorgados; excesso → responsabilidade pessoal.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q17", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q17", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Sociedade simples: registro no RCPJ (Registro Civil de Pessoas Jurídicas); sociedade empresária: Junta Comercial.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M5-Q18", "bloco": "MÓDULO 5 — Teoria Geral das Sociedades Empresárias", "num": "Q18", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Incidente de desconsideração da personalidade jurídica (art. 133 CPC): instaurado pelo juiz ou a requerimento da parte; suspende o processo principal.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q1", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q1", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Sociedade em comum: sem registro; todos respondem solidária e ilimitadamente (art. 990 CC); prova da existência entre sócios = qualquer meio; para terceiros = qualquer meio também (art. 987).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q2", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q2", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Sociedade em conta de participação: sócio ostensivo responde com terceiros (obrigações em seu nome); sócio participante responde apenas entre si.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q3", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q3", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Sociedade simples: patrimônio social responde primeiro (art. 1.024); sócios respondem subsidiariamente se contrato não limitar.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q4", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q4", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Contrato social: elementos obrigatórios — nome e qualificação dos sócios, denominação, objeto, sede, capital social, prazo (art. 997 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q5", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q5", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Sociedade em nome coletivo: <b>todos</b> os sócios respondem ilimitada e solidariamente; apenas pessoas físicas como sócios.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q6", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q6", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Em comandita simples: comanditado (ilimitada) + comanditário (limitada à quota). Comanditário não pode praticar atos de gestão.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q7", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q7", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Sociedade limitada: capital dividido em quotas; responsabilidade dos sócios limitada ao valor das quotas subscritas + solidária pela integralização.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q8", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q8", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Sociedade anônima: capital dividido em ações; responsabilidade limitada ao preço de emissão; sempre empresarial (art. 1.089 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q9", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q9", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Em comandita por ações: diretores respondem ilimitada e subsidiariamente; demais acionistas = limitada. Regida pela LSA (Lei 6.404/76).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q10", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q10", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Classificação das sociedades: por pessoas (relevância do sócio) vs. por capital (relevância do capital — como a S/A).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q11", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q11", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Sociedade cooperativa: não é sociedade empresária nem simples stricto sensu — tem legislação própria; sobras ≠ lucro.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q12", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q12", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Sociedade anônima aberta: ações negociadas em bolsa/mercado; sujeita à CVM; obrigações de transparência mais rígidas.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q13", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q13", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Sociedade por cotas de responsabilidade limitada: nome atual é \"sociedade limitada\" (CC/2002); cotas = quotas.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q14", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q14", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Tipos societários pessoais: sociedade em comum, simples, em nome coletivo, em comandita simples. Sócio mais importante que o capital.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q15", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q15", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Sociedade simples: registro no RCPJ; pode adotar estrutura de qualquer tipo societário exceto anônima (art. 983 § único CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q16", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q16", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Dissolução total da sociedade: causas — término do prazo; consenso dos sócios; falta de pluralidade &gt;180 dias; extinção da autorização; anulação da constituição; falência; decisão judicial.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q17", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q17", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Sociedade de propósito específico (SPE): criada para projeto específico; extingue-se com a conclusão do objeto.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M6-Q18", "bloco": "MÓDULO 6 — Sociedades Empresárias — Espécies", "num": "Q18", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Empresa Individual de Responsabilidade Limitada (EIRELI): foi absorvida pela SLU (Sociedade Limitada Unipessoal) no CC/2002 com a Lei 14.195/21.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q1", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q1", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Quotas na Ltda: indivisíveis em relação à sociedade; sócios respondem solidariamente pela integralização (art. 1.052 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q2", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q2", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Cessão de quotas: requer aprovação de sócios com ≥ 3/4 do capital social, se contrato não dispuser diferente (art. 1.057 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q3", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q3", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Integralização de quotas: em dinheiro ou bens; <b>vedado</b> integralizar com prestação de serviços (art. 1.055 §2º CC). Diferente das cooperativas.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q4", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q4", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Usufruto de quota: possível; nu-proprietário conserva direito à quota; usufrutuário tem direitos patrimoniais. Votação = definida em contrato.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q5", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q5", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Aumento de capital: deliberação de sócios que representem ≥ 3/4 do capital (quórum qualificado); sócios têm preferência na subscrição.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q6", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q6", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Administração da Ltda: pode ser exercida por sócio ou não sócio (pessoa física capaz); designado no contrato ou em ato separado.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q7", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q7", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Redução de capital: somente se não houver oposição de credores quirografários (prazo 90 dias para oposição — art. 1.084 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q8", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q8", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Responsabilidade do administrador Ltda: pelos atos praticados com culpa ou dolo no exercício das funções (art. 1.016 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q9", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q9", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Reunião de sócios: obrigatória quando mais de 10 sócios; anual para aprovar balanço e distribuir resultados (art. 1.072 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q10", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q10", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Exclusão extrajudicial de sócio: falta grave; votos de sócios representando + 50% do capital (excluindo o sócio acusado).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q11", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q11", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Dissolução da Ltda: parcial (exclusão/morte/retirada de sócio) ou total (art. 1.033 CC — decurso do prazo, falência, decisão judicial etc.).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q12", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q12", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Penhor de quota: possível; credor pignoratício não tem direito a voto, mas tem direito ao resultado.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q13", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q13", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "Sociedade de grande porte: obrigada a adotar contabilidade e auditoria como S/A (Lei 11.638/07 art. 3º) mesmo sendo Ltda.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q14", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q14", "tema": "", "enun": "", "gab": "E", "gabLabel": "", "html": "LSA aplicada subsidiariamente à Ltda quando o contrato social optar expressamente (art. 1.053 § único CC).", "repete": true, "repeteRef": "Q13", "coment": []}, {"id": "M7-Q15", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q15", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Penhora de quota: credor pode penhorar quota do sócio devedor; mas para liquidar, precisa aguardar a dissolução ou exercício de preferência pelos sócios.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q16", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q16", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Deliberações Ltda — quórum qualificado (3/4 capital): mudança de objeto, fusão, incorporação, cisão, transformação, dissolução.", "repete": true, "repeteRef": "nos flashcards", "coment": []}, {"id": "M7-Q17", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q17", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Administrador não sócio: possível; nomeado no contrato ou em ato separado; responsabilidade pelos atos de gestão.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M7-Q18", "bloco": "MÓDULO 7 — Sociedade Limitada", "num": "Q18", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Condomínio de quota: quando quota pertence a mais de uma pessoa; direitos exercidos por representante comum (art. 1.056 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q1", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q1", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "S/A: capital dividido em ações; responsabilidade = limitada ao preço de emissão; sempre empresarial (arts. 1.088 e 1.089 CC).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q2", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q2", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Sistema legal da S/A: Lei 6.404/76 (LSA); Código Comercial regulou de 295 a 299; hoje = LSA + CC subsidiariamente.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q3", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q3", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Histórico: origem nas associações navais medievais (colonna) e nas companhias holandesas do séc. XVII.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q4", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q4", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Características da S/A: capital em ações, responsabilidade limitada, livre negociabilidade de ações, denominação (não firma), sempre empresarial.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q5", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q5", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Objeto social: qualquer lícito e lucrativo; sempre empresarial independentemente do objeto — diferença da Ltda (pode ser simples se objeto intelectual).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q6", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q6", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Denominação: \"Sociedade Anônima\" ou \"S/A\" ou \"Companhia\"/\"Cia.\" — NÃO usa firma (nome de sócios). Cia. não pode ser usada no final da denominação.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q7", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q7", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Companhia aberta vs. fechada: aberta = ações negociadas em bolsa/mercado de balcão, sujeita à CVM; fechada = restrita a grupo de acionistas.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q8", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q8", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Capital da S/A: sempre em moeda nacional; formado por qualquer espécie de bens avaliáveis em dinheiro; avaliação por 3 peritos ou empresa especializada.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q9", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q9", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Ações: ordinárias (voto), preferenciais (privilégios, podem não ter voto), de gozo/fruição (amortizadas com manutenção de direitos residuais).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q10", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q10", "tema": "", "enun": "", "gab": "B", "gabLabel": "", "html": "Forma das ações: sempre <b>nominativas</b> (desde Lei 8.021/90); ações ao portador e endossáveis foram extintas.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q11", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q11", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Certificados de ações: emitidos só após cumpridas as formalidades legais; ações escriturais: mantidas em conta de depósito sem emissão de certificado.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q12", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q12", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Integralização das ações: pode ser parcelada conforme estatuto; acionista devedor de prestações sujeito a cobrança e juros moratórios.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q13", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q13", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Indivisibilidade: ação é indivisível em relação à companhia; condomínio de ação = representante comum exerce os direitos.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q14", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q14", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Negociação de ações próprias: em regra, proibida; exceções: resgate/reembolso, compra com lucros/reservas (sem diminuir capital), doação.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q15", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q15", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Companhia não pode ter como único acionista pessoa jurídica nacional (exceto subsidiária integral — art. 251 LSA).", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q16", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q16", "tema": "", "enun": "", "gab": "A", "gabLabel": "", "html": "Amortização: antecipação de valor que o acionista receberia na liquidação; total ou parcial; por sorteio se não abranger todas as ações.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q17", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q17", "tema": "", "enun": "", "gab": "D", "gabLabel": "", "html": "Reembolso: direito do acionista dissidente de receber o valor de suas ações quando deliberação modificar direitos essenciais.", "repete": false, "repeteRef": "", "coment": []}, {"id": "M8-Q18", "bloco": "MÓDULO 8 — Sociedade Anônima", "num": "Q18", "tema": "", "enun": "", "gab": "C", "gabLabel": "", "html": "Assembleia Geral: órgão soberano da S/A; AGO anual (4 meses após fim do exercício); AGE — quando necessário.", "repete": false, "repeteRef": "", "coment": []}], "sinteses": [], "cards": [{"id": "c1", "f": "O que é empresário segundo o CC/2002?", "v": "Quem exerce profissionalmente atividade econômica organizada para produção ou circulação de bens ou serviços (art. 966 CC). Requisitos: profissionalismo, organização, atividade econômica.\n\n---"}, {"id": "c2", "f": "Qual o limite de faturamento do MEI, ME e EPP?", "v": "MEI: até R$ 81 mil/ano | ME: até R$ 360 mil/ano | EPP: R$ 360.001 a R$ 4.800.000/ano (LC 123/06).\n\n---"}, {"id": "c3", "f": "Qual o prazo da patente de invenção e do modelo de utilidade?", "v": "Patente de invenção: 20 anos do depósito. Modelo de utilidade: 15 anos do depósito (LPI 9.279/96).\n\n---"}, {"id": "c4", "f": "Por quanto tempo uma marca registrada no INPI é protegida?", "v": "10 anos da concessão, renováveis indefinidamente por períodos iguais de 10 anos.\n\n---"}, {"id": "c5", "f": "Qual o prazo do desenho industrial?", "v": "10 anos do depósito, prorrogável por 3 períodos de 5 anos → máximo 25 anos.\n\n---"}, {"id": "c6", "f": "O que diferencia sociedade empresária de sociedade simples?", "v": "Empresária: objeto = atividade de empresário (produção/circulação organizada), registro na Junta Comercial. Simples: atividade intelectual (científica, literária, artística), registro no RCPJ.\n\n---"}, {"id": "c7", "f": "Qual a diferença entre dissolução total e resolução parcial da sociedade?", "v": "Dissolução: extinção da sociedade. Resolução parcial: saída de um sócio (morte, exclusão, retirada) — a sociedade continua existindo.\n\n---"}, {"id": "c8", "f": "Quais cônjuges não podem ser sócios entre si?", "v": "Casados em comunhão universal de bens ou separação obrigatória de bens (art. 977 CC).\n\n---"}, {"id": "c9", "f": "Quando nasce a personalidade jurídica de uma sociedade?", "v": "Com o registro (art. 985 CC). Sem registro = sociedade em comum (não personificada), todos respondem solidária e ilimitadamente.\n\n---"}, {"id": "c10", "f": "O que é o trespasse e qual a restrição ao alienante?", "v": "Trespasse = alienação do estabelecimento empresarial. O alienante fica proibido de se restabelecer como concorrente por 5 anos (art. 1.147 CC), salvo autorização expressa.\n\n---"}, {"id": "c11", "f": "Quais os requisitos da ação renovatória de locação?", "v": "(1) Contrato escrito; (2) prazo mínimo de 5 anos (pode ser soma de contratos); (3) exploração do mesmo ramo por no mínimo 3 anos; (4) proposta formulada 1 ano antes e no máximo 6 meses antes do fim do contrato.\n\n---"}, {"id": "c12", "f": "Qual é a responsabilidade dos sócios na Sociedade Limitada?", "v": "Limitada ao valor das quotas subscritas, porém todos respondem solidariamente pela integralização total do capital (art. 1.052 CC).\n\n---"}, {"id": "c13", "f": "Que quórum é necessário para cessão de quotas na Ltda?", "v": "Aprovação de sócios representando pelo menos 3/4 do capital social, salvo disposição contrária no contrato.\n\n---"}, {"id": "c14", "f": "O que é a Sociedade Anônima e qual sua responsabilidade?", "v": "Capital dividido em ações; responsabilidade dos acionistas limitada ao preço de emissão das ações subscritas. Sempre empresarial (art. 1.089 CC).\n\n---"}, {"id": "c15", "f": "Qual a diferença entre S/A aberta e fechada?", "v": "Aberta: ações negociadas em bolsa ou mercado de balcão, sujeita à CVM. Fechada: ações restritas a grupo de acionistas, sem negociação pública.\n\n---"}, {"id": "c16", "f": "Que tipo de nome usa a S/A — firma ou denominação?", "v": "Denominação (inclui objeto + \"S/A\", \"Companhia\" ou \"Cia.\" — mas \"Cia.\" não pode ser usado ao final). Não usa firma (nome de sócios).\n\n---"}, {"id": "c17", "f": "Quais os tipos de ações de uma S/A?", "v": "Ordinárias (direito a voto), Preferenciais (privilégios econômicos, podem não ter voto) e De Gozo/Fruição (entregues a acionistas que tiveram suas ações amortizadas).\n\n---"}, {"id": "c18", "f": "Como uma marca pode ser cancelada por falta de uso?", "v": "Caducidade: se o titular não usar a marca por 5 anos consecutivos após a concessão, pode ser declarada caduca pelo INPI a pedido de terceiro com interesse legítimo (art. 143 LPI).\n\n---"}, {"id": "c19", "f": "O que é a desconsideração da personalidade jurídica inversa?", "v": "Responsabiliza a sociedade pelas dívidas pessoais de seus sócios (art. 50 §§ 2º e 3º CC), quando o sócio usa a pessoa jurídica para blindar patrimônio pessoal.\n\n---"}, {"id": "c20", "f": "Quais deliberações na Ltda exigem quórum de 3/4 do capital?", "v": "Mudança de objeto social, fusão, incorporação, cisão, transformação, dissolução e qualquer modificação do contrato que o exija. Cessar de quotas também requer 3/4 salvo disposição contrária."}], "cobertura": ["O próprio arquivo avisa: onde o texto completo da questão não foi extraído, o comentário se baseia no gabarito e no conteúdo do módulo. Parte dos comentários, portanto, é dedução e não texto do AVA.", "Os arquivos trazem gabarito e comentário. Enunciados e alternativas completas não vieram.", "Este material não passou por conferência automática nem por auditoria independente. As frases não trazem citação literal da fonte."], "notas": [{"esc": "revisao", "ref": "r7", "titulo": "Contradiz os flashcards", "texto": "O resumo diz que mudança de objeto, fusão e dissolução na Ltda exigem unanimidade. O flashcard 20 e a Q16 do Módulo 7 dizem 3/4 do capital, que é o que consta nos arts. 1.071 e 1.076 do CC. Confira no AVA."}, {"esc": "card", "ref": "c13", "titulo": "Cessão de quotas: regra mais precisa", "texto": "O art. 1.057 do CC permite a cessão a outro sócio sem consulta, e a estranho se não houver oposição de titulares de mais de 1/4 do capital. “Aprovação de 3/4” é uma simplificação. Veja como o AVA formula."}, {"esc": "questao", "ref": "M7-Q2", "titulo": "Cessão de quotas: regra mais precisa", "texto": "Mesma observação do flashcard 13 (art. 1.057 do CC)."}, {"esc": "card", "ref": "c20", "titulo": "Erro de digitação e mesma observação", "texto": "“Cessar de quotas” deve ser cessão de quotas. Para o quórum, veja a observação do flashcard 13."}, {"esc": "card", "ref": "c2", "titulo": "Limite do MEI", "texto": "O teto de R$ 81 mil segue vigente em 2026. Há notícia de lei sancionada que o eleva a R$ 110 mil em 2027 e R$ 140 mil em 2028. Para a prova de 2026, vale o R$ 81 mil."}, {"esc": "questao", "ref": "M2-Q3", "titulo": "EIRELI foi extinta", "texto": "A Lei 14.195/21 extinguiu a EIRELI e a transformou em sociedade limitada unipessoal (como diz a Q18 do Módulo 6). Questão histórica do AVA. Siga o gabarito."}, {"esc": "questao", "ref": "M2-Q4", "titulo": "EIRELI foi extinta", "texto": "As regras de nome e capital citadas valiam para a EIRELI, extinta pela Lei 14.195/21. Siga o gabarito do AVA."}, {"esc": "questao", "ref": "M4-Q12", "titulo": "Lei citada provavelmente errada", "texto": "A topografia de circuito integrado tem lei própria (Lei 11.484/2007), não o art. 25 da LPI. Tema de baixa prioridade."}, {"esc": "questao", "ref": "M8-Q15", "titulo": "Frase confusa", "texto": "A regra é: a companhia precisa de pelo menos dois acionistas, salvo a subsidiária integral, cujo único acionista é sociedade brasileira (art. 251 da LSA). O comentário está mal redigido."}]};